+    const brackets = [
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 500 },
+      { upToGrams: 5000, costCents: 1000 },
+    ];
+
+    it("returns 0 for empty cart", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(calc.computeShippingCents([], 5000)).toBe(0);
+    });
+
+    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      const lines: CartLine[] = [
+        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
+      ];
+      expect(calc.computeShippingCents(lines, 200)).toBe(0);
+    });
+
+    it("selects first bracket that fits the weight", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 250g total → first bracket (≤500g) → 300 cents
+      expect(calc.computeShippingCents([makeLine("a", 250, 1)], 1000)).toBe(
+        300,
+      );
+    });
+
+    it("selects exact boundary bracket", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // exactly 500g → first bracket
+      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(
+        300,
+      );
+      // exactly 501g → second bracket
+      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(
+        500,
+      );
+    });
+
+    it("selects higher bracket for heavier items", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 3000g → third bracket (≤5000g) → 1000
+      expect(calc.computeShippingCents([makeLine("a", 1000, 3)], 5000)).toBe(
+        1000,
+      );
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      const calc = new WeightBasedShippingCalculator(brackets, 2000);
+      // 6000g > 5000 → overflow → 2000
+      expect(calc.computeShippingCents([makeLine("a", 2000, 3)], 5000)).toBe(
+        2000,
+      );
+    });
+
+    it("defaults overflow to heaviest bracket cost when not provided", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 6000g > 5000 → last bracket cost = 1000
+      expect(calc.computeShippingCents([makeLine("a", 2000, 3)], 5000)).toBe(
+        1000,
+      );
+    });
+
+    it("sorts brackets by upToGrams regardless of input order", () => {
+      const unsorted = [
+        { upToGrams: 5000, costCents: 1000 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 1000, costCents: 500 },
+      ];
+      const calc = new WeightBasedShippingCalculator(unsorted);
+      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(
+        300,
+      );
+    });
+
+    it("accumulates weight from multiple lines", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      const lines = [makeLine("a", 300, 1), makeLine("b", 250, 1)];
+      // 300 + 250 = 550g → second bracket (≤1000g) → 500
+      expect(calc.computeShippingCents(lines, 2000)).toBe(500);
+    });
+  });
+});
